"""Regression cases for legacy icon alpha, GDI ownership and cooperative HID."""
import sys,pathlib,copy,json,time,threading,struct,ctypes,hashlib,marshal,types
import app,config as cfg,auth,hid_layer as hid
from actions import obs
from PyQt6.QtCore import QTimer,QEvent
from PyQt6.QtWidgets import QApplication
import speed_editor_context as context,speed_editor_usability as ux
import speed_editor_performance as performance
ROOT=pathlib.Path(sys.executable).parent;cfg.CONFIG_FILE=str(ROOT/'config.json')
auth.is_signed_in=lambda:False;auth.get_user_email=lambda:'';obs.client.connect=lambda *args:False
app.hotkey_action.send=lambda *args:None;context.OFFLINE=True
ux.atomic_save(copy.deepcopy(cfg.DEFAULT_CONFIG));application=QApplication([])
window=app.MainWindow();window.show()
report={'source_sha256':'__SOURCE_SHA256__','checks':[]}
def check(name,result,details=None):
    report['checks'].append({'name':name,'pass':bool(result),'details':details})
    (ROOT/'icon-hid-report.json').write_text(json.dumps(report,indent=2),encoding='utf8')
    assert result,name+': '+repr(details)
try:
    check('nine native icon sizes available',[s.width() for s in window.windowIcon().availableSizes()]==list(performance.ICON_SIZES))
    check('tray and main use exactly the same icon',window._background.tray.icon().cacheKey()==window.windowIcon().cacheKey())
    # A deliberately old ICO: every XOR alpha byte is zero; transparency comes
    # only from its AND mask. This previously became invisible or a black box.
    size=32;pixels=bytearray();mask=bytearray()
    for y in reversed(range(size)):
        row=bytearray(4)
        for x in range(size):
            opaque=8<=x<24 and 8<=y<24
            pixels.extend((40,32,224,0) if opaque else (0,0,0,0))
            if not opaque:row[x//8]|=1<<(7-x%8)
        mask.extend(row)
    blob=struct.pack('<IiiHHIIiiII',40,size,2*size,1,32,0,0,0,0,0,0)+pixels+mask
    ico=struct.pack('<HHH',0,1,1)+struct.pack('<BBBBHHII',size,size,0,0,1,32,len(blob),22)+blob
    legacy=ROOT/'legacy-alpha.ico';legacy.write_bytes(ico)
    image_icon=performance.native_icon(str(legacy),32)
    check('legacy AND-mask icon is extracted',image_icon is not None and not image_icon.isNull())
    image=image_icon.pixmap(32,32).toImage()
    check('legacy opaque center remains red',image.pixelColor(16,16).alpha()>250 and image.pixelColor(16,16).red()>200)
    check('legacy transparent corner remains transparent',image.pixelColor(0,0).alpha()==0)
    own=performance.native_icon(sys.executable,32)
    check('PE executable icon has visible colored center',own is not None and own.pixmap(32,32).toImage().pixelColor(16,16).alpha()>250)
    user=ctypes.WinDLL('user32');kernel=ctypes.WinDLL('kernel32')
    kernel.GetCurrentProcess.restype=ctypes.c_void_p;user.GetGuiResources.argtypes=[ctypes.c_void_p,ctypes.c_uint]
    before=user.GetGuiResources(kernel.GetCurrentProcess(),0)
    samples=[]
    for _ in range(12):
        extracted=performance.native_icon(str(legacy),32).pixmap(32,32).toImage()
        samples.append(hashlib.sha256(bytes(extracted.bits().asstring(extracted.sizeInBytes()))).hexdigest())
    after=user.GetGuiResources(kernel.GetCurrentProcess(),0)
    check('native extraction is deterministic',len(set(samples))==1)
    check('native icon extraction releases GDI handles',after<=before+3,{'before':before,'after':after})
    performance.STOP_EVENT.clear();calls=[];read_started=threading.Event()
    class Handle:
        def read(self,length,timeout):
            calls.append((length,timeout));read_started.set();time.sleep(timeout/1000);return [3]
        def close(self):calls.append('close')
    device=object.__new__(hid.SpeedEditor);device.dev=Handle();device._reauth_timer=None;device._shutdown_io_lock=threading.RLock()
    handlers=[];device._handle_03=lambda data:handlers.append(data);device._handle_04=lambda data:None;device._handle_07=lambda data:None
    worker=threading.Thread(target=device.run,daemon=True);worker.start();assert read_started.wait(1)
    at=time.monotonic();performance.STOP_EVENT.set();worker.join(1);elapsed=time.monotonic()-at
    check('HID read poll uses a bounded 100 ms timeout',calls[0]==(64,100),calls)
    check('HID read stops within 250 ms',not worker.is_alive() and elapsed<.25,elapsed)
    check('a report returning after quit is not dispatched',not handlers)
    device.close();device.close()
    check('HID device closes exactly once',calls.count('close')==1 and device.dev is None)
    # Invoke the exact packaged reconnect-loop code with inert fixtures.
    main_code=marshal.loads(bytes.fromhex(''))
    def find(code):
        if code.co_name=='hid_thread':return code
        for const in code.co_consts:
            if isinstance(const,types.CodeType):
                found=find(const)
                if found:return found
    retry_code=find(main_code);attempted=threading.Event();attempts=[]
    def no_device():attempts.append(1);attempted.set();raise OSError('isolated missing device')
    signal=types.SimpleNamespace(emit=lambda *args:None)
    values={'_se':None,'on_key':lambda *args:None,'on_jog':lambda *args:None,'signals':types.SimpleNamespace(device_status=signal),'time':time}
    cell=lambda value:(lambda:value).__closure__[0]
    callback=types.FunctionType(retry_code,{'SpeedEditor':no_device,'__builtins__':__builtins__},closure=tuple(cell(values[name]) for name in retry_code.co_freevars))
    performance.STOP_EVENT.clear();retry=threading.Thread(target=callback,daemon=True);retry.start();assert attempted.wait(1)
    at=time.monotonic();performance.STOP_EVENT.set();retry.join(.3)
    check('three-second device retry wakes immediately on quit',not retry.is_alive() and time.monotonic()-at<.3)
    check('device reconnect cannot continue after quitting',len(attempts)==1)
    report['passed']=True
except BaseException:
    import traceback
    (ROOT/'icon-hid-error.txt').write_text(traceback.format_exc(),encoding='utf8');raise
finally:
    window.action_panel._ux_revert();window._background.quit_action.trigger()
    deadline=time.monotonic()+3
    while window._shutdown.workers() and time.monotonic()<deadline:
        application.processEvents();time.sleep(.005)
    for top in QApplication.topLevelWidgets():top.deleteLater()
    QApplication.sendPostedEvents(None,QEvent.Type.DeferredDelete)
    (ROOT/'icon-hid-report.json').write_text(json.dumps(report,indent=2),encoding='utf8')
QTimer.singleShot(0,application.quit);application.exec()
sys.exit(0)
